export function BattleTimeline(a,l){return`<div class="battles-timeline">${[...a].sort((a,l)=>a.year-l.year).map(a=>{const t=l[a.era]||{label:a.era,color:"#888"};return`\n            <div class="timeline-battle-event" data-era="${a.era}">\n                <div class="tl-dot" style="background: ${t.color}"></div>\n                <div class="tl-content">\n                    <div class="tl-meta">\n                        <span class="tl-year">${a.date}</span>\n                        <span class="tl-era-badge" style="background: ${t.color}20; color: ${t.color}">${t.label}</span>\n                    </div>\n                    <h4 class="tl-battle-name">${a.name}</h4>\n                    <p class="tl-location">${a.location}</p>\n                    <p class="tl-outcome">${a.outcome}</p>\n                </div>\n            </div>\n        `}).join("")}</div>`}